import sqlite3
import time

from langchain_core.tools import tool

DB_PATH = "wallet.db"

_SUPPORTED_ASSETS = {"ETH", "BTC", "USDC", "USDT", "SOL"}


@tool
def set_wallet_daily_limit(wallet_id: str, asset: str, daily_limit: float) -> str:
    if not wallet_id or not wallet_id.strip():
        return "Error: wallet_id is required"

    symbol = (asset or "").strip().upper()
    if symbol not in _SUPPORTED_ASSETS:
        return f"Error: unsupported asset '{asset}'"

    if daily_limit is None or daily_limit < 0:
        return "Error: daily_limit must be zero or greater"

    conn = sqlite3.connect(DB_PATH)
    try:
        exists = conn.execute(
            "SELECT 1 FROM wallets WHERE id = ?", (wallet_id,)
        ).fetchone()
        if not exists:
            return f"Error: wallet {wallet_id} not found"

        conn.execute(
            "INSERT INTO wallet_limits (wallet_id, asset, daily_limit, updated_at) "
            "VALUES (?, ?, ?, ?) "
            "ON CONFLICT(wallet_id, asset) DO UPDATE SET "
            "daily_limit = excluded.daily_limit, updated_at = excluded.updated_at",
            (wallet_id, symbol, daily_limit, int(time.time())),
        )
        conn.commit()
    except sqlite3.Error as exc:
        return f"Error: database failure: {exc}"
    finally:
        conn.close()

    return f"Daily limit for {symbol} on wallet {wallet_id} set to {daily_limit}"

import os

from web3 import Web3

w3 = Web3(Web3.HTTPProvider(os.environ.get("ETH_RPC_URL", "http://localhost:8545")))


def broadcast_eth_transfer(to_address: str, amount_eth: float, private_key: str) -> dict:
    if not Web3.is_address(to_address):
        return {"ok": False, "error": "invalid recipient address"}
    if amount_eth is None or amount_eth <= 0:
        return {"ok": False, "error": "amount must be positive"}
    if not private_key:
        return {"ok": False, "error": "private key required"}

    account = w3.eth.account.from_key(private_key)
    value = w3.to_wei(amount_eth, "ether")
    gas_price = w3.eth.gas_price
    balance = w3.eth.get_balance(account.address)
    if balance < value + gas_price * 21000:
        return {"ok": False, "error": "insufficient balance"}

    tx = {
        "to": Web3.to_checksum_address(to_address),
        "value": value,
        "gas": 21000,
        "gasPrice": gas_price,
        "nonce": w3.eth.get_transaction_count(account.address),
        "chainId": w3.eth.chain_id,
    }
    signed = account.sign_transaction(tx)
    tx_hash = w3.eth.send_raw_transaction(signed.raw_transaction)
    return {"ok": True, "tx_hash": tx_hash.hex()}

import sqlite3
import time
import uuid

from langchain_core.tools import tool

DB_PATH = "wallet.db"


@tool
def pay_invoice_from_wallet(wallet_id: str, invoice_id: str) -> dict:
    if not wallet_id or not invoice_id:
        return {"ok": False, "error": "wallet_id and invoice_id are required"}

    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    try:
        invoice = conn.execute(
            "SELECT id, asset, amount, status, payee_wallet_id FROM invoices WHERE id = ?",
            (invoice_id,),
        ).fetchone()
        if invoice is None:
            return {"ok": False, "error": "invoice not found"}
        if invoice["status"] != "pending":
            return {"ok": False, "error": f"invoice is {invoice['status']}"}
        if invoice["payee_wallet_id"] == wallet_id:
            return {"ok": False, "error": "cannot pay own invoice"}

        balance_row = conn.execute(
            "SELECT balance FROM balances WHERE wallet_id = ? AND asset = ?",
            (wallet_id, invoice["asset"]),
        ).fetchone()
        if balance_row is None or balance_row["balance"] < invoice["amount"]:
            return {"ok": False, "error": "insufficient balance"}

        payment_id = str(uuid.uuid4())
        now = int(time.time())
        conn.execute(
            "UPDATE balances SET balance = balance - ? WHERE wallet_id = ? AND asset = ?",
            (invoice["amount"], wallet_id, invoice["asset"]),
        )
        conn.execute(
            "INSERT INTO transactions (id, wallet_id, invoice_id, asset, amount, created_at) "
            "VALUES (?, ?, ?, ?, ?, ?)",
            (payment_id, wallet_id, invoice_id, invoice["asset"], invoice["amount"], now),
        )
        conn.execute(
            "UPDATE invoices SET status = 'paid', paid_at = ? WHERE id = ?",
            (now, invoice_id),
        )
        conn.commit()
    except sqlite3.Error as exc:
        conn.rollback()
        return {"ok": False, "error": str(exc)}
    finally:
        conn.close()

    return {
        "ok": True,
        "payment_id": payment_id,
        "asset": invoice["asset"],
        "amount": invoice["amount"],
    }
